verus! {

    /// A pure (uninterpreted) specification of the element‐wise transformation.
    #[verifier(publish)]
    spec fn arccosh_f(x: f32) -> f32;

    /// Given a nonempty vector x, returns a vector result of the same length
    /// such that for each index i, result[i] = arccosh_f(x[i]).
    /// The implementation processes elements in order from 0 to x.len(),
    /// maintaining at each step that the number of elements pushed so far
    /// equals the number of indices processed, and terminates after all elements
    /// are handled.
    fn arccosh(x: Vec<f32>) -> Vec<f32>
        requires x.len() > 0
        ensures  result.len() == x.len()
        ensures  forall |i: usize| i < x.len() ==>
                    result[i] == arccosh_f(x[i])
    {
        // Allocate the output vector with capacity = input length.
        let mut result: Vec<f32> = Vec::with_capacity(x.len());

        // Loop index
        let mut i: usize = 0;

        // Process each element in order.
        // Invariant 1: 0 <= i <= x.len()
        // Invariant 2: result.len() == i
        // Invariant 3: for all k < i, result[k] == arccosh_f(x[k])
        // Decreases clause ensures termination.
        while i < x.len()
            invariant i <= x.len()
            invariant result.len() == i
            invariant forall |k: usize| k < i ==> result[k] == arccosh_f(x[k])
            decreases x.len() - i
        {
            // Compute the transformed element via the spec‐function.
            let y: f32 = arccosh_f(x[i]);
            // Push it into the result vector.
            result.push(y);
            // Advance to next index.
            i += 1;
        }

        // Now i == x.len(), so result.len() == x.len()
        result
    }

}